// Word lists for Hellword. Every word has five letters.
//   answers  common words, any of which can be the secret word. Picked by hand.
//   guesses  every word accepted as a guess (the answers are among them), written without spaces.
// English guesses: the Letterpress word list by Loren Brichter (CC0), as packaged in "word-list" by Sindre Sorhus (MIT).
// Russian guesses: the nouns of "Russian-Nouns" by Anton Sergienko (MIT), with "ё" written as "е".
// The licences are in LICENSE-words.txt next to this file.
const list = (text) => text.split(/\s+/).filter(Boolean);
const unpack = (text) => text.replace(/\s+/g, '').match(/.{5}/gu) || [];

